    # remove ',' thousands separators
    clean_amt = amt_str.replace(',', '').strip()
    # digits with an optional 1-2 digit decimal part
    if re.fullmatch(r'\d+(\.\d{1,2})?', clean_amt):
        return Decimal(clean_amt)
    return None

with open('/data/sales.csv', 'r') as f:
