        if d is None: reasons.append(f'invalid date {date_str}')
        if not curr_ok: reasons.append(f'invalid currency {currency}')
        if amt is None: reasons.append(f'invalid amount {amount}')
        if reasons:
            print(f'Line {line_num} REJECT: order_id={order_id}, {reasons}')
        else:
            print(f'Line {line_num} ACCEPT: order_id={order_id}, date={d}, curr={currency.strip().upper()}, amt={amt}, status={status.strip()}')
